class Solution {
  public List<Integer> inorderTraversal(TreeNode root) {
    List<Integer> order = new ArrayList<>();
    traverse(root, order);
    return order;
  }
  private void traverse(TreeNode node, List<Integer> order) {
    if (node == null) return;
    traverse(node.left, order);
    order.add(node.val);
    traverse(node.right, order);
  }
}

